import{_ as e,H as t,f as n,i as s}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"03｜初识MetaGPT","description":"","frontmatter":{},"headers":[{"level":2,"title":"安装 Python、Node.js 和 Git","slug":"安装-python、node-js-和-git","link":"#安装-python、node-js-和-git","children":[]},{"level":2,"title":"Python 项目初始化","slug":"python-项目初始化","link":"#python-项目初始化","children":[]},{"level":2,"title":"安装 MetaGPT 并运行第一个例子","slug":"安装-metagpt-并运行第一个例子","link":"#安装-metagpt-并运行第一个例子","children":[]},{"level":2,"title":"MetaGPT官方文档导读","slug":"metagpt官方文档导读","link":"#metagpt官方文档导读","children":[]},{"level":2,"title":"第二个例子：人类参与的多 Agent 应用","slug":"第二个例子-人类参与的多-agent-应用","link":"#第二个例子-人类参与的多-agent-应用","children":[]},{"level":2,"title":"总结时刻","slug":"总结时刻","link":"#总结时刻","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"LLM自主智能体应用实战课/03｜初识MetaGPT.md","filePath":"LLM自主智能体应用实战课/03｜初识MetaGPT.md","lastUpdated":1779815961000}'),p={name:"LLM自主智能体应用实战课/03｜初识MetaGPT.md"};function i(l,a,o,r,c,d){return t(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="_03-初识metagpt" tabindex="-1">03｜初识MetaGPT <a class="header-anchor" href="#_03-初识metagpt" aria-label="Permalink to &quot;03｜初识MetaGPT&quot;">​</a></h1><p>你好，我是李锟。</p><p>这节课我们正式进入实战环节，开始学习本课程第一个 Autonomous Agent 开发框架—— <strong>MetaGPT，也是目前此类开发框架中最为成熟的一个。</strong></p><p>目前 Python 是 AI + LLM 应用开发的首选编程语言，我们这套课程中使用的编程语言是 Python，选择的开发框架也是 Python 开发框架。其他编程语言例如 Java、C#、JavaScript、Go 等语言的开发者，暂时无法兼顾，只能说抱歉了。</p><h2 id="安装-python、node-js-和-git" tabindex="-1">安装 Python、Node.js 和 Git <a class="header-anchor" href="#安装-python、node-js-和-git" aria-label="Permalink to &quot;安装 Python、Node.js 和 Git&quot;">​</a></h2><p>在 Linux 主机上需要确保有符合要求的 Python 版本。在 Ubuntu 上安装 Python 的方法很多，你可以自行搜索。理想情况下，Ubuntu 自带的 Python 版本即可满足要求。从兼容性的角度，Python 的版本我推荐使用官方的 3.10 版。</p><p>虽然 Python 最新的官方版本已经是 3.13 版，但仍然有很多 AI、LLM 开发库无法在 3.12 以上版本中使用。所以以后对于要学习的每个开发框架，除非我明确说明可使用 Python 3.12 以上版本，否则都使用 3.10 或 3.11 版。使用 Conda 安装的 Python 也是可以的，只要对应的 Python 版本满足上述要求。</p><p>在 Python 环境中，需要提前安装好 poetry，因为我们将使用 poetry 这个强大的工具来创建和管理 Python 虚拟环境。安装方法：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pip3 install poetry</span></span></code></pre></div><p>注意：在安装完 poetry 之后，还要确保将 poetry 命令所在目录加入到 PATH 环境变量中，以便以后可以在命令行直接调用。</p><p>还需要在 Linux 主机上安装好 Node.js 和一些 MetaGPT 会用到的基于 Node.js 的工具。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt install nodejs build-essential</span></span>
<span class="line"><span>sudo npm install -g &amp;#64;mermaid-js/mermaid-cli</span></span>
<span class="line"><span>npx puppeteer browsers install chrome-headless-shell</span></span></code></pre></div><p>在 Linux 主机上安装好 Git。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install git</span></span></code></pre></div><h2 id="python-项目初始化" tabindex="-1">Python 项目初始化 <a class="header-anchor" href="#python-项目初始化" aria-label="Permalink to &quot;Python 项目初始化&quot;">​</a></h2><p>首先我们需要初始化一个 Python 项目，在 Linux 主机的终端窗口执行以下命令：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkdir -p ~/work/learn_metagpt</span></span>
<span class="line"><span>cd ~/work/learn_metagpt</span></span>
<span class="line"><span>touch README.md</span></span>
<span class="line"><span>poetry init</span></span>
<span class="line"><span># 创建 poetry 虚拟环境，当出现以下提示</span></span>
<span class="line"><span>Compatible Python versions [^3.10]:  时，输入 &quot;&amp;gt;=3.9, &amp;lt;3.12&quot; (注意别加引号)</span></span></code></pre></div><p>因为众所周知的原因，我建议使用国内的 Python 库镜像服务器，例如上海交大的镜像服务器：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>poetry source add --priority=primary mirrors https://mirror.sjtu.edu.cn/pypi/web/simple</span></span></code></pre></div><p>如果上海交大镜像服务器的访问速度很慢，也可以使用其他镜像服务器，你可以自己搜索其他镜像服务器的地址。</p><p>然后安装一些常用的 Python 库：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>poetry add pysocks socksio</span></span></code></pre></div><p>MetaGPT 项目的创始人是吴承霖老师，于 2023 年 6 月开源。</p><p>项目的源代码在： <a href="https://github.com/geekan/MetaGPT" target="_blank" rel="noreferrer">https://github.com/geekan/MetaGPT</a></p><p>官方文档在： <a href="https://docs.deepwisdom.ai/main/zh/guide/get_started/introduction.html" target="_blank" rel="noreferrer">https://docs.deepwisdom.ai/main/zh/guide/get_started/introduction.html</a></p><p>因为 MetaGPT 是由中国开发者创建并主导的，所以有很好的中文文档。</p><p>这里我就不花时间赘述 MetaGPT 的历史了，你可以自己搜索阅读网上的资料。闲话少述，我们直接进入主题，在项目中安装 MetaGPT，运行一些官方提供的例子。</p><h2 id="安装-metagpt-并运行第一个例子" tabindex="-1">安装 MetaGPT 并运行第一个例子 <a class="header-anchor" href="#安装-metagpt-并运行第一个例子" aria-label="Permalink to &quot;安装 MetaGPT 并运行第一个例子&quot;">​</a></h2><p>MetaGPT 的安装方法主要有两种：Python 库安装和项目源代码安装 (最新的开发版本)。因为即将发布的 MetaGPT 1.0 版与当前的 0.8.x 稳定版相比变化很大，所以我推荐基于项目最新的源代码 (见下面的命令) 安装，以便学习到最新的知识，能够长期有效。</p><p>执行以下命令安装 MetaGPT 及其依赖的 Python 库：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd ~/work</span></span>
<span class="line"><span>git clone https://github.com/geekan/MetaGPT.git</span></span>
<span class="line"><span>cd learn_metagpt</span></span>
<span class="line"><span># poetry add --editable &quot;../MetaGPT&quot;</span></span>
<span class="line"><span>poetry install --no-root &amp;&amp; poetry run pip install -e &quot;../MetaGPT&quot; --config-settings editable_mode=compat</span></span></code></pre></div><p>还记得在上一课的结尾，我们在 Linux 主机上使用 ollama 部署了一个开源 LLM——阿里巴巴的 qwen2.5。确保以下命令：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ollama run qwen2.5</span></span></code></pre></div><p>能够正常运行。然后我们使用这个开源 LLM 来运行 MetaGPT 官方提供的例子。</p><p>运行第一个 MetaGPT 例子前，需要给项目添加一个配置文件。建议你把配置文件放在 ~/.metagpt 目录下。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkdir ~/.metagpt</span></span>
<span class="line"><span>vi ~/.metagpt/config2.yaml</span></span></code></pre></div><p>输入以下内容：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>llm:</span></span>
<span class="line"><span>  api_type: &#39;ollama&#39;</span></span>
<span class="line"><span>  base_url: &#39;http://127.0.0.1:11434/api&#39;</span></span>
<span class="line"><span>  model: &#39;qwen2.5&#39;</span></span>
<span class="line"><span>  temperature: 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>CALC_USAGE: True</span></span>
<span class="line"><span>repair_llm_output: true</span></span></code></pre></div><p>保存配置文件 config2.yaml，然后执行以下命令，看看会发生什么神奇的事情。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>poetry run metagpt &quot;write a cli blackjack game&quot;</span></span></code></pre></div><p>屏幕上出现了长串输出的文本和代码，滚动了很长时间。请耐心等待一段时间，运行期间可以去做些其他事情，或者喝杯咖啡偷个懒 😃 。</p><p>如果在输出中没有报告任何错误，说明命令执行是成功的。输出中有一些警告：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Model qwen2.5 not found in TOKEN_COSTS</span></span></code></pre></div><p>对于当前的 MetaGPT 0.8.x 稳定版，因为在系统中没有配置通过 ollama 支持的开源 LLM 的 token 费率，出现这个警告是正常的，可以简单忽略。在 MetaGPT 最新的开发版中已经解决了这个问题。</p><p>上述这个简单的命令究竟做了些什么？我向 MetaGPT 提出了一个要求：编写一个可在命令行运行的 21 点 (BlackJack) 游戏 。但是我并没有告诉 MetaGPT 21 点游戏究竟是啥，它通过底层 LLM 的理解能力和搜索工具自己搞清楚了这件事，并且写出了可以运行的 Python 代码（默认编程语言是 Python，也可以生成其他语言的代码）。</p><p>如果需要保存 metagpt 命令输出的内容，可以将屏幕输出重定向到一个文件。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>poetry run metagpt &quot;write a cli blackjack game&quot; &amp;gt; blackjack.txt</span></span></code></pre></div><p>运行完成后，可以使用编辑器打开 blackjack.txt，看看 MetaGPT 所生成的代码。有兴趣的话，还可以亲自把这些代码跑一下。</p><p>与 Autonomous Agent 的初次邂逅感觉如何？是不是与以前使用过的各种 ChatBot 的体验迥异？我们可以直观体会到， <strong>Autonomous Agent 与 ChatBot 的主要区别就是自主性和自动化程度。</strong> MetaGPT 完成我提出的编程要求，确实花了较长时间，但是如果自动生成的源代码大多数是可用的，带来的价值远远超出了所花费的时间。</p><p>那么生成的这些代码是否真的可用呢？里面会不会有 bug？这个问题跟我们所使用的基础 LLM 的能力有关，不同的 LLM 在生成代码方面的能力差距会很大。我们在这里所使用的 qwen2.5 在生成代码方面，是开源 LLM 中的佼佼者。代码质量的这个问题目前并不是重点，我们暂时先放下。</p><p>我们可以把默认情况下的 MetaGPT 看作是一个标准的 <strong>软件开发团队</strong>，其中有架构师、程序员、测试工程师等等不同的角色。团队的产出物是可编译、可运行并通过了测试的软件源代码。但是使用 MetaGPT 不仅能组建一个软件开发团队，MetaGPT 事实上能组建各种不同类型的工作团队。在下一课我们将要开发一个能够陪伴我们玩 24 点游戏的智能体应用，我们并不需要它给我们编一套 24 点游戏的 Python 代码，而是希望它像一个人类一样能直接陪伴我们玩这个游戏。</p><h2 id="metagpt官方文档导读" tabindex="-1">MetaGPT官方文档导读 <a class="header-anchor" href="#metagpt官方文档导读" aria-label="Permalink to &quot;MetaGPT官方文档导读&quot;">​</a></h2><p>MetaGPT 有很棒的官方文档，在我们课程中重复介绍免费的官方文档是毫无意义的。所以我会补充官方文档中没有提及的内容。前面我也说过，本课程可以看作是一个武林秘籍的目录，而不是取代这些武林秘籍。要深入掌握一个开发框架， <strong>通读官方文档</strong> 是不能免去的功课，因此我在这里对官方文档做一个导读。</p><p>MetaGPT 官方文档中，初学者首先需要阅读最前面这三个部分。</p><ul><li><p>概念简述： <a href="https://docs.deepwisdom.ai/main/zh/guide/tutorials/concepts.html" target="_blank" rel="noreferrer">https://docs.deepwisdom.ai/main/zh/guide/tutorials/concepts.html</a></p></li><li><p>智能体入门： <a href="https://docs.deepwisdom.ai/main/zh/guide/tutorials/agent_101.html" target="_blank" rel="noreferrer">https://docs.deepwisdom.ai/main/zh/guide/tutorials/agent_101.html</a></p></li><li><p>多智能体入门： <a href="https://docs.deepwisdom.ai/main/zh/guide/tutorials/multi_agent_101.html" target="_blank" rel="noreferrer">https://docs.deepwisdom.ai/main/zh/guide/tutorials/multi_agent_101.html</a></p></li></ul><p>首先需要理解关于多 Agent 应用的一些核心概念。你不要急于运行示例代码，先认真阅读一下上述概念简述，这里我仅引用该文档里的一小部分内容：</p><blockquote><p>学术界和工业界对术语“ <strong>智能体</strong>” (Agent) 提出了各种定义。大致来说，一个智能体应具备类似人类的思考和规划能力，拥有记忆甚至情感，并具备一定的技能以便与环境、智能体和人类进行交互。</p><p>在 MetaGPT 看来，可以将智能体想象成环境中的数字人，其中</p><p><strong>智能体 = 大语言模型（LLM） + 观察 + 思考 + 行动 + 记忆</strong></p><p><strong>多智能体</strong> (MultiAgent) 系统可以视为一个智能体社会，其中</p><p><strong>多智能体 = 智能体 + 环境 + 标准流程（SOP） + 通信 + 经济</strong></p></blockquote><p>在概念简述文档中，对上述两个公式中右侧的各个名词也给出了详细的解释。这些概念是 MetaGPT 设计的基础，我们理解了这些概念，再去理解其他 Autonomous Agent 开发框架的设计也会容易很多。现代 AI 研究方法的理论基础—— <strong>深度学习</strong> 其实是基于 <strong>仿生学</strong>，也就是通过计算机软件模拟人类的脑科学。MetaGPT 对于 Agent 和多 Agent 的理解，同样也是基于仿生学。我们可以把一个 Agent 理解为一个像人类一样有智能的实体，可以通过自然语言来与之交互。多个 Agent 可以组合在一起，通过自然语言彼此沟通，并开展复杂的协作。</p><p>在官方文档中给出了一个简单的多 Agent 协作的图示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%E8%87%AA%E4%B8%BB%E6%99%BA%E8%83%BD%E4%BD%93%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98%E8%AF%BE/images/840276/53b0571e78ce5ac5940aecce879340f3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%E8%87%AA%E4%B8%BB%E6%99%BA%E8%83%BD%E4%BD%93%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98%E8%AF%BE/images/840276/53b0571e78ce5ac5940aecce879340f3.png" alt="图片"></a></p><p>MetaGPT 最初设计和实现的典型场景是一个软件开发团队，所以这个图示是一个极简的软件开发团队。虽然这只是一个简单的图示，我们可以从中了解到很多信息：</p><ul><li><p>每个 Agent 都有自己的角色 (也可以理解为岗位)。在这个图示中，Alice 作为产品经理编写需求文档；Bob 作为项目经理，分配任务并对生成的代码做出评价；Charlie 作为程序员，根据需求和任务描述编写 Python 代码。每个 Agent 仅完成自己这个角色需要完成的任务，各司其职，通过协作完成复杂的工作。这就是所谓的 <strong>Role Playing</strong>(角色扮演)，更好地支持 Role Playing 正是目前各个基础 LLM 的一个重要的改进方向。</p></li><li><p>同一个团队中的多个 Agent 共享一个环境。它们通过从环境接收和向环境发送各种事件来开展通信和协作。</p></li><li><p>环境中的事件有多种类型，最重要的事件是 <strong>执行Action</strong>。执行每个Action (一个事件) 的输出结果会累积起来，作为接收这个事件的 Agent 将要执行的后续 Action 的输入上下文。每个 Agent 可订阅环境中自己感兴趣的任何 Action，并且基于这些 Action 的输出结果开展思考，确定自己需要执行的后续 Action。</p></li><li><p>执行 Action 时可以根据需要调用各种外部工具 ，完成某个任务并且返回执行结果。外部工具可以做需要的任何事情，包括访问搜索引擎、查询数据库、在订票网站上订飞机票、启动设备生产一批零件等等。</p></li><li><p>每个 Agent 都有自己的记忆，能够记住自己之前与其他智能体开展的对话、接收到的事件、采取的行动。并且根据记忆做出适合的决策，执行适合的 Action。</p></li></ul><p>通过阅读 MetaGPT 官方文档的前三个部分，还可以了解到，在一个多 Agent 应用中，每一个 Agent 既可以由程序 (机器人) 来担任，也可以由人类用户来担任。听起来非常有趣是吧？</p><p>MetaGPT 的设计目标之一就是让人类用户与各种智能体完美协作。我们很快就会体会到，这样的设计非常灵活和强大。因为在一些复杂的协作中，当基础 LLM 尚不够强大时，由人类来承担关键角色，做出决策和评判是很重要的。LLM 同样也不是银弹，但是它是人类很好的辅助工具。在 <strong>百分之百自动化</strong> 难以实现时，能够大幅提高工作效率、降低工作成本的 <strong>半自动化</strong> 工作流同样也是值得追求的。</p><h2 id="第二个例子-人类参与的多-agent-应用" tabindex="-1">第二个例子：人类参与的多 Agent 应用 <a class="header-anchor" href="#第二个例子-人类参与的多-agent-应用" aria-label="Permalink to &quot;第二个例子：人类参与的多 Agent 应用&quot;">​</a></h2><p>第一个例子是通过 metagpt 命令运行的，我们没有看到源代码，会感觉隔靴搔痒。接下来我们来看一个更简单的例子，一个支持人类用户参与的多 Agent 应用例子，示例代码在课程代码文件 build_customized_multi_agents.py 中。</p><p>在这个示例代码中有三个 Role 的子类 (即前面图示中的 Agent)：一个程序员 SimpleCoder、一个测试工程师 SimpleTester、一个评论员 SimpleReviewer。由 SimpleReviewer 确定生成的代码质量是否可以接受以及工作是否成功完成。示例代码中每个 Agent 的名字和角色划分，与前面的图示有些差别，注意别搞混了。代码略微有点长，就不占用篇幅了，你可以自己用编辑器打开代码文件查看。</p><p>使用以下命令运行这个例子：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>poetry run python build_customized_multi_agents.py --idea &quot;write a function that calculates the product of a list&quot; --add_human=True</span></span></code></pre></div><p>在上述命令中，我提出的任务要求是，编写一个 Python 函数来计算列表中的产品数量。这里有一个参数 “add_human=True”，默认为 False。如果设置为 True，则由人类用户来充当评论员，对生成的代码做出评价。执行上述命令时，在输出生成的代码之后，会在命令行等待用户的输入，可以简单输入“It’s OK”以结束程序执行。</p><p>从这个例子的代码可以看出，在一个典型的 MetaGPT 应用中，包含了三个层次：Team (团队)、Role (角色) 和 Action (行动)。</p><ul><li><p>一个 Team 可包含 (雇佣) 多个 Role。在这个例子中，Team 包含了三个 Role：SimpleCoder、SimpleTester、SimpleReviewer。</p></li><li><p>每个 Role 可包含 (执行) 一个或多个 Action。SimpleCoder 包含了 SimpleWriteCode、SimpleTester 包含了 SimpleWriteTest、SimpleReviewer 包含了 SimpleWriteReview。</p></li></ul><p>当传入“–add_human=True”选项时，在初始化 SimpleReviewer 对象时会传入一个“is_human=True”参数，这样 SimpleReviewer 就不再执行 SimpleWriteReview 这个 Action 来获得对代码的评价，而是在命令行等待人类用户输入代码的评价。</p><p>这个简单的例子比较容易理解。大多数神奇的事情是由开发框架实现的，我们在这里只需要理解高层的抽象即可。每个 Role 对象都是事件驱动的，在这里的事件就是各个 Action。在运行之前每个 Role 对象首先注册自己可执行的 Action，以及自己感兴趣的 Action。然后这些不同的 Action 按照串行和并行方式组合在一起，构成一个复杂的工作流。</p><p>从这个例子的代码再结合对之前图示的讲解，我们还可以了解到以下细节：</p><ul><li><p>每个 Action 对象的 run() 函数的输出，会累积起来，作为接收这个事件的 Role 对象后续执行的 Action 对象 run() 函数的输入参数 context。</p></li><li><p>如果系统的工作流是单一串行的，在 Role 对象的初始化函数中，只需要注册自己可以执行的 Action，和订阅自己感兴趣的 Action。例如 SimpleReviewer 对象的初始化函数：</p></li></ul><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>     def __init__(self, **kwargs):</span></span>
<span class="line"><span>        super().__init__(**kwargs)</span></span>
<span class="line"><span>        self.set_actions([SimpleWriteReview])</span></span>
<span class="line"><span>        self._watch([SimpleWriteTest])</span></span></code></pre></div><p>需要注意的是，这里的提示词 (Prompt) 默认都是英文的。这也是目前大多数 Autonomous Agent 开发框架的要求。这对于 Autonomous Agent 来说不是一个大问题。因为这类应用并不需要使用者手写大量的提示词。如果使用者不熟悉英文，找一个翻译工具翻译一下也非常简单。</p><h2 id="总结时刻" tabindex="-1">总结时刻 <a class="header-anchor" href="#总结时刻" aria-label="Permalink to &quot;总结时刻&quot;">​</a></h2><p>在这一课中，我们使用 poetry 创建了 Python 项目，在项目中安装了 MetaGPT。通过运行第一个例子验证 MetaGPT 可正常工作。然后我们阅读了 MetaGPT 官方文档的前三个部分，理解了 MetaGPT 的核心概念。最后运行了第二个例子，并研究了第二个例子的源代码。运行两个例子均使用优秀的国产开源 LLM——阿里巴巴的 qwen2.5。</p><p>MetaGPT 最初的设计就是为了支持多 Agent 协作的，堪称目前最完善的多 Agent 开发框架。吴承霖老师说他在 2023 年上半年看过大多数开源 LLM 应用开发框架（包括 LangChain），没有一个能支持多 Agent 协作，无奈之下只好自己动手，开启了一段传奇经历。</p><p>在下一课中，我们开始使用 MetaGPT 实现我们真正的需求——一个陪伴我们玩24点游戏的智能体应用。</p><p>课程代码链接： <a href="https://gitee.com/mozilla88/autonomous_agent/tree/master/lesson_03" target="_blank" rel="noreferrer">https://gitee.com/mozilla88/autonomous_agent/tree/master/lesson_03</a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>在 MetaGPT 应用中不同的 Agent (Role 的子类实例) 是如何协作的？</p><p>提示：通过在 build_customized_multi_agents.py 源代码中各个 Role 和 Action 对象的函数内添加 print 或 logger 语句，搞清楚它们之间是如何协作的。</p><p>期待你的分享。如果今天的内容对你有所帮助，也期待你转发给你的同事或者朋友，大家一起学习，共同进步。我们下节课再见！</p>`,87)])])}const u=e(p,[["render",i]]);export{g as __pageData,u as default};
